    }, {
        "label": "label4",
        "value": "value4",
        "gubun": "B"
    }];
    dataList2.setJSON(jsonData2);
    var jsonData = [{
        "col1": "A",
        "col2": "12341234\n12341234",
        "col3": "value1"
    }, {
        "col1": "A",
