scwin.onpageunload = function() {};
scwin.gridView1_onviewchange = function(info) {
    //debugger;
};
scwin.trigger1_onclick = function(e) {
    //현재 선택값을 문자열로 반환
    var chkValue = checkcombobox1.getValue(",");
    var chkText = checkcombobox1.getText(",");
    //현재 선택값을 배열로 반환
    var chkValueArr = checkcombobox1.getValueArray();
    var chkTextArr = checkcombobox1.getTextArray()
    var rowIdx = gridView1.getFocusedRowIndex();
    var grdData = dataList1.getRowJSON(rowIdx);
    var jsonData = {
        "chkcombo": chkValue
        //,"col1":grdData["col1"]
        //,"col2":grdData["col2"] 
    };
    dataMap1.setJSON(jsonData);
    //$w.executeSubmission("submission1");
    var options = {
        type: "1",
        fileName: "aaa.xlsx",
        useStyle: "true",
        bodyWordwrap: true
    };
    gridView1.advancedExcelDownload(options);
};
scwin.chkcomboCFn = function(data, formattedData, row, col) {
    console.log("customFormatter: ", arguments);
    return data;
};
scwin.customLablFormatter = function(itemArr, isOpen) {
    console.log("customLabelFormatter: ", itemArr, isOpen);
    var customArr = itemArr;
    var retArr = [];
    for (var i = 0; i < customArr.length; i++) {
        // {index: 2, label: "label3", value: "value3"}
        customArr[i].label = itemArr[i].label + " 라벨";
        retArr.push(customArr[i].label);
    }
    return retArr.join(", ");
    // return customArr;
};
scwin.disFn = function(value) {
    console.log("displayFormatter: ", value);
    var half = value.length / 2;
    return value;
    //return value.substring(0, half)+"\n"+value.substring(half);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+$p.id+'gridView1_cell_0_2').innerText == 'value1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
